  "inputSourceName": "project/src/S2SRegistry.sol",
  "devdoc": {
    "events": {
      "ReservedSet(bytes32,bool,string)": {
        "details": "`handle` is carried so an indexer can recover the reserved spelling,      not just the skeleton it folds to."
      }
    },
    "kind": "dev",
    "methods": {
      "assignReserved(string,address,address)": {
        "details": "The `recordsLocation` argument exists because the pointer must be      written at registration and governance cannot read it later. The      reserved flag is left set: a released name returns to the pool, not      to public registration.      `Reserved()` is the failed precondition here as well as the refusal      in `register`: this function requires the skeleton to be in the      reserved set, and the error set has no separate `NotReserved`."
      },
      "check(string)": {
        "details": "Caller-independent: it does not consider whether the caller already      holds another handle. `register` still reverts `AlreadyRegistered`      in that case.      Reasons 1..3 precede the storage checks; a name that fails the      structure rules returns that reason even when it is also reserved."
      },
      "constructor": {
        "params": {
          "_authorGate": "The author gate. Must have code: it is called on every        registration and assignment.",
          "_governance": "The governance address. Must have code and be non-zero;        governance must be able to send a transaction (a Safe or a        governance executor), because every governance function is        `msg.sender == governance`."
        }
      },
      "register(string,address)": {
        "details": "Order is fixed: one handle per Safe, then the gate, then the name      rules. `recordsLocation` must be the Safe's own enabled records      module — the gate checks that it answers `safe()` with `msg.sender` —      so a registration cannot point at another author's module."
      },
      "skeletonOf(string)": {
        "details": "Canonical even for input `register` would refuse, so callers can use      it to compare spellings before validation. Validation uses the same      private function, so a rule change cannot make `check` disagree with      `register`."
      }
    },
    "stateVariables": {
      "REASON_FREE": {
        "details": "`check` reasons, exported so callers and tests read the same numbers."
      },
      "coolingUntil": {
        "details": "Skeleton hash → the timestamp before which no one may claim it."
      },
      "entries": {
        "details": "Keyed `keccak256(bytes(handle))`. Deleted on release."
      },
      "handleOf": {
        "details": "The handle a Safe currently holds, or zero."
      },
      "lastVersion": {
        "details": "The last version ever assigned per handle hash. `entries[h]` is      deleted on release, so this is the only record that keeps a      re-registration from restarting at 1 and reusing a version."
      },
      "reserved": {
        "details": "Skeleton hashes governance keeps out of public registration."
      },
      "skeletonOwner": {
        "details": "Skeleton hash → the handle hash that claimed it. Cleared on release,      which is what frees the spellings together."
      }
    },
    "title": "S2SRegistry",
    "version": 1
  },
